 </main><div class="toast" id="toast"></div>
 <script>
+const cars=[
+ {name:'Vortex GT-R',year:'2021 · JAPANESE COUPE · RWD',price:8500,color:'#d5fb43',stats:[7,8,7],speed:188,accel:1.04,handling:1.02},
+ {name:'Kestrel R-Spec',year:'2019 · EUROPEAN SPORT · AWD',price:11000,color:'#ff684b',stats:[9,7,8],speed:204,accel:1.11,handling:1.04},
+ {name:'Mirage X',year:'2022 · STREET HYPER · RWD',price:14500,color:'#56d7e6',stats:[10,9,6],speed:226,accel:1.20,handling:.91}
+];
+const rivals=[{name:'Mick “Sideways”',avatar:'😎',wallet:14500},{name:'Vee Torque',avatar:'🦊',wallet:17000},{name:'Uncle Nitro',avatar:'🧔',wallet:21000}];
+const state={cash:18000,round:0,car:{name:'Starter Coupe',speed:168,accel:.98,handling:.95,color:'#d4fc43',stats:[6,6,6]},currentBid:0,asking:0,highBidder:'none',playerOffer:0,playerWon:[],rival:null,auctionTimer:18,auctionActive:false,raceRunning:false,finished:false,raceDist:0,raceTime:0,boost:100,playerLane:1,obstacles:[],opponents:[],lastFrame:0,gameFrame:0,roundsWon:0};
+const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
+function show(id){$$('.screen').forEach(x=>x.classList.toggle('active',x.id===id));}
+function money(n){return '$'+Math.max(0,Math.floor(n)).toLocaleString('en-US')}
+function cashUpdate(){$('#cash').textContent=money(state.cash)}
+function toast(msg){const t=$('#toast');t.innerHTML=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
+function carSvg(color){return `<svg viewBox="0 0 260 155" aria-hidden="true"><ellipse cx="130" cy="130" rx="99" ry="13" fill="#0006"/><path fill="${color}" d="M22 94 32 77q4-8 17-11l34-9 24-29q7-8 19-9l46-3q13 0 22 9l26 32 20 7q9 3 12 13l4 24q1 10-10 12l-18 2q-3-24-25-24t-27 25l-81 2q-3-25-24-25t-25 25l-24-2q-9-1-10-11l-1-8q0-8 12-10z"/><path fill="#1c222c" d="m111 32 54-3q8 0 14 7l19 25H91l19-25q1-3 5-4z"/><path fill="#9eb4bc" d="m115 35 46-3-2 26h-66z"/><path fill="#d1e4e6" d="m166 32 4 1q5 1 9 6l17 22h-31z"/><path fill="#242a35" d="m29 79 40-9-5 10-36 8zm159-11 21 3 13 10h-26z"/><path fill="#fff2bd" d="m230 87 8 3 1 9-11-1z"/><path fill="#ff4f63" d="m24 91 9-2-2 9-9 2z"/><circle cx="77" cy="111" r="19" fill="#11151d"/><circle cx="77" cy="111" r="9" fill="#8b929c"/><circle cx="77" cy="111" r="4" fill="#303744"/><circle cx="209" cy="111" r="19" fill="#11151d"/><circle cx="209" cy="111" r="9" fill="#8b929c"/><circle cx="209" cy="111" r="4" fill="#303744"/><path fill="#fff" opacity=".55" d="m84 61 19-25 2 25z"/></svg>`}
+function renderCar(car){$('#auctionCar').innerHTML=carSvg(car.color);$('#carName').textContent=car.name;$('#carYear').textContent=car.year;$('#asking').textContent=money(car.price);$('#lotNo').textContent='LOT '+String(state.round+1).padStart(3,'0');$('#roundNum').textContent=String(state.round+1).padStart(2,'0');$('#roundEyebrow').textContent='ROUND '+(state.round+1);$('#carStats').innerHTML=['SPEED','ACCEL','GRIP'].map((n,i)=>`<div class="stat"><div class="stat-icon">${['↗','ϟ','⌁'][i]}</div><div><div class="stat-name">${n} <b style="color:#e9edf4">${car.stats[i]}/10</b></div><div class="stat-track"><div class="stat-fill" style="width:${car.stats[i]*10}%"></div></div></div></div>`).join('');}
+function startAuction(){if(state.round>=cars.length){endSeason();return}const car=cars[state.round];state.rival=rivals[(state.round+1)%rivals.length];state.asking=car.price;state.currentBid=Math.floor(car.price*.47/100)*100;state.highBidder='none';state.playerOffer=0;state.auctionTimer=18;state.auctionActive=true;state.rivalNext=2+Math.random()*2.2;state.rivalCeiling=Math.min(state.rival.wallet,car.price*(1.55+Math.random()*.38));renderCar(car);$('#rivalAvatar').textContent=state.rival.avatar;$('#rivalName').textContent=state.rival.name;$('#rivalStatus').textContent='is eyeing the lot...';$('#rivalOffer').textContent='—';$('#bidStatus').textContent='You're watching the lot.';$('#bidStatus').className='bid-status';$('#bidHint').textContent=`Your maximum: ${money(state.cash)}`;$('#bidAmount').innerHTML=`<span>$</span> ${state.currentBid.toLocaleString()}`;updateBidBtn();show('auction');clearInterval(state.auctionClock);state.auctionClock=setInterval(auctionTick,1000);}
+function nextOffer(){return state.currentBid+1000}
+function updateBidBtn(){let offer=nextOffer();$('#bidBtn').textContent=`PLACE BID · ${money(offer)}`;$('#bidBtn').disabled=offer>state.cash||!state.auctionActive;$('#bidHint').textContent=offer>state.cash?'Not enough cash for the next bid.':`Your maximum: ${money(state.cash)}`;}
+function setBid(n){if(!state.auctionActive)return;state.currentBid=Math.max(0,Math.min(state.cash,Math.round((state.currentBid+n)/100)*100));$('#bidAmount').innerHTML=`<span>$</span> ${state.currentBid.toLocaleString()}`;updateBidBtn();}
+function playerBid(){if(!state.auctionActive)return;let offer=nextOffer();if(offer>state.cash){toast('Not enough cash for that bid.');return}state.currentBid=offer;state.playerOffer=offer;state.highBidder='player';$('#bidAmount').innerHTML=`<span>$</span> ${offer.toLocaleString()}`;$('#bidStatus').textContent='You’re the high bidder. Hold your nerve.';$('#bidStatus').className='bid-status good';$('#rivalStatus').textContent='is thinking it over...';$('#rivalOffer').textContent='OUTBID';updateBidBtn();state.auctionTimer=Math.min(18,state.auctionTimer+3);}
+function rivalBid(){if(!state.auctionActive)return;let offer=state.currentBid+1000;if(offer>state.rivalCeiling||offer>state.rival.wallet){$('#rivalStatus').textContent='has backed away.';$('#rivalOffer').textContent='PASSED';state.rivalNext=999;return}state.currentBid=offer;state.highBidder='rival';$('#bidAmount').innerHTML=`<span>$</span> ${offer.toLocaleString()}`;$('#rivalOffer').textContent=money(offer);$('#rivalStatus').textContent='just raised the stakes!';$('#bidStatus').textContent='You’ve been outbid. Raise or pass?';$('#bidStatus').className='bid-status warn';updateBidBtn();state.auctionTimer=Math.min(18,state.auctionTimer+2);}
+function auctionTick(){if(!state.auctionActive)return;state.auctionTimer--;$('#timer').textContent='00:'+String(Math.max(0,state.auctionTimer)).padStart(2,'0');$('#timerFill').style.width=Math.max(0,state.auctionTimer/18*100)+'%';state.rivalNext--;if(state.rivalNext<=0&&state.highBidder!=='rival'&&state.rivalOffer!=='PASSED'){rivalBid();state.rivalNext=2.3+Math.random()*2.6;}if(state.auctionTimer<=0)settleAuction();}
+function settleAuction(){if(!state.auctionActive)return;state.auctionActive=false;clearInterval(state.auctionClock);if(state.highBidder==='player'){const car=cars[state.round];state.cash-=state.currentBid;state.car={...car,stats:[...car.stats]};state.playerWon.push(car.name);$('#bidStatus').textContent=`SOLD! ${car.name} is yours.`;$('#bidStatus').className='bid-status good';cashUpdate();toast(`<em>HAMMER DOWN!</em> ${car.name} yours for ${money(state.currentBid)}`);}else{state.rival.wallet-=state.currentBid;$('#bidStatus').textContent='SOLD! The lot goes to '+(state.highBidder==='rival'?state.rival.name:'the room')+'.';$('#bidStatus').className='bid-status warn';toast('Lot sold. Your cash stays safe.');}updateBidBtn();}
+function passLot(){if(state.auctionActive){state.auctionActive=false;clearInterval(state.auctionClock);$('#bidStatus').textContent='You passed. The lot goes to the room.';$('#bidStatus').className='bid-status';toast('Lot passed — save your cash for the next one.');updateBidBtn();}}
+function goRace(){if(state.auctionActive)settleAuction();startRace();}

