function goRace(){if(state.auctionActive)settleAuction();startRace();}
const canvas=$('#game'),ctx=canvas.getContext('2d');
let keys={left:false,right:false,boost:false,up:false},touches={left:false,right:false,boost:false};
const raceLength=1800;
function startRace(){show('race');state.raceRunning=true;state.finished=false;state.raceDist=0;state.raceTime=0;state.boost=100;state.playerLane=1;state.obstacles=[];state.gameFrame=0;state.raceStart=performance.now();state.lastFrame=0;state.opponents=[{name:'Mick',lane:0,color:'#ff684b',dist:-70,speed:162+state.round*5},{name:'Vee',lane:2,color:'#5bd8e6',dist:-130,speed:158+state.round*5},{name:'Nitro',lane:1,color:'#b36cff',dist:-210,speed:155+state.round*5}];$('#raceRound').textContent=String(state.round+1).padStart(2,'0');$('#raceCarName').textContent=state.car.name;$('#raceTopSpeed').textContent=state.car.speed+' km/h';$('#raceProgress').style.width='0%';$('#raceMessage').textContent='GO! GO! GO!';$('#positionHud').textContent='4 / 4';resizeCanvas();requestAnimationFrame(raceLoop);}
function resizeCanvas(){const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*dpr);canvas.height=Math.floor(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
function laneX(lane,y,w){const horizon=canvas.clientHeight*.31,roadBottom=canvas.clientWidth*.91,roadTop=canvas.clientWidth*.34,p=(y-horizon)/(canvas.clientHeight-horizon),roadW=roadTop+(roadBottom-roadTop)*p,left=canvas.clientWidth/2-roadW/2;return left+roadW*(lane+.5)/3;}
function drawCar(x,y,w,h,color,player=false){ctx.save();ctx.translate(x,y);if(player)ctx.rotate((keys.left||touches.left?-.035:0)+(keys.right||touches.right?.035:0));ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(0,h*.36,w*.57,h*.19,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-w*.5,h*.25);ctx.lineTo(-w*.43,-h*.13);ctx.lineTo(-w*.28,-h*.43);ctx.quadraticCurveTo(0,-h*.54,w*.28,-h*.43);ctx.lineTo(w*.44,-h*.12);ctx.lineTo(w*.5,h*.26);ctx.quadraticCurveTo(0,h*.38,-w*.5,h*.26);ctx.fill();ctx.fillStyle='#17212a';ctx.beginPath();ctx.moveTo(-w*.29,-h*.16);ctx.lineTo(-w*.2,-h*.37);ctx.quadraticCurveTo(0,-h*.45,w*.2,-h*.37);ctx.lineTo(w*.31,-h*.14);ctx.fill();ctx.fillStyle='#acc6c8';ctx.globalAlpha=.7;ctx.fillRect(-w*.18,-h*.35,w*.35,h*.12);ctx.globalAlpha=1;ctx.fillStyle='#ff4949';ctx.fillRect(-w*.41,h*.16,w*.15,h*.07);ctx.fillRect(w*.26,h*.16,w*.15,h*.07);ctx.fillStyle='#10141c';ctx.fillRect(-w*.55,-h*.08,w*.13,h*.29);ctx.fillRect(w*.42,-h*.08,w*.13,h*.29);if(player&& (keys.boost||touches.boost)&&state.boost>0){ctx.fillStyle='#baf9ff';ctx.globalAlpha=.7;ctx.beginPath();ctx.moveTo(-w*.18,h*.31);ctx.lineTo(-w*.12,h*.31);ctx.lineTo(-w*.13,h*.6);ctx.fill();ctx.beginPath();ctx.moveTo(w*.12,h*.31);ctx.lineTo(w*.19,h*.31);ctx.lineTo(w*.12,h*.59);ctx.fill();}ctx.restore();}
function drawRoad(){const W=canvas.clientWidth,H=canvas.clientHeight,horizon=H*.31;ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#141a29');sky.addColorStop(1,'#59616a');ctx.fillStyle=sky;ctx.fillRect(0,0,W,horizon);ctx.fillStyle='#1b2526';ctx.fillRect(0,horizon,W,H-horizon);for(let i=0;i<18;i++){let x=(i*91+state.gameFrame*.18)% (W+70)-35,hh=18+(i*31%38);ctx.fillStyle=i%2?'#202635':'#252a36';ctx.fillRect(x,horizon-hh,28+(i%4)*8,hh+3);ctx.fillStyle='#d2fc43';for(let j=0;j<3;j++)if((i+j)%3)ctx.fillRect(x+5+j*8,horizon-hh+8,3,4);}
const p=state.raceDist/18;const topW=W*.34,bottomW=W*.91,leftTop=W/2-topW/2,leftBottom=W/2-bottomW/2;ctx.fillStyle='#363c43';ctx.beginPath();ctx.moveTo(leftTop,horizon);ctx.lineTo(leftTop-topW*.11,H);ctx.lineTo(leftBottom+bottomW+bottomW*.11,H);ctx.lineTo(leftTop+topW,horizon);ctx.fill();ctx.fillStyle='#292e34';ctx.beginPath();ctx.moveTo(leftTop,horizon);ctx.lineTo(leftBottom,H);ctx.lineTo(leftBottom+bottomW,H);ctx.lineTo(leftTop+topW,horizon);ctx.fill();ctx.fillStyle='#d4fc43';ctx.beginPath();ctx.moveTo(leftTop-2,horizon);ctx.lineTo(leftBottom-4,H);ctx.lineTo(leftBottom+3,H);ctx.lineTo(leftTop+2,horizon);ctx.fill();ctx.beginPath();ctx.moveTo(leftTop+topW-2,horizon);ctx.lineTo(leftBottom+bottomW-3,H);ctx.lineTo(leftBottom+bottomW+4,H);ctx.lineTo(leftTop+topW+2,horizon);ctx.fill();
const shift=(p*2.7)%1;for(let lane=1;lane<=2;lane++){for(let i=0;i<8;i++){let t=(i+shift)/8,y=horizon+(H-horizon)*t;if(y>horizon){let roadW=topW+(bottomW-topW)*t,x=W/2-roadW/2+roadW*lane/3;ctx.fillStyle='#c8cbd0';ctx.globalAlpha=.7;ctx.fillRect(x-1.6*t,y,3.2*t,20*t+2);ctx.globalAlpha=1;}}}
// road-side lamps
for(let i=0;i<5;i++){let t=((i/4+shift*.13)%1),y=horizon+(H-horizon)*t,xEdge=W/2-(topW+(bottomW-topW)*t)/2-12*t;ctx.strokeStyle='#718080';ctx.lineWidth=2*t+1;ctx.beginPath();ctx.moveTo(xEdge,y);ctx.lineTo(xEdge-1*t,y-28*t);ctx.lineTo(xEdge+10*t,y-28*t);ctx.stroke();ctx.fillStyle='#d4fc43';ctx.globalAlpha=.65;ctx.fillRect(xEdge+7*t,y-30*t,5*t,3*t);ctx.globalAlpha=1;ctx.beginPath();ctx.moveTo(W-xEdge,y);ctx.lineTo(W-xEdge+1*t,y-28*t);ctx.lineTo(W-xEdge-10*t,y-28*t);ctx.stroke();ctx.fillRect(W-xEdge-12*t,y-30*t,5*t,3*t);}
}
function drawRace(){drawRoad();const W=canvas.clientWidth,H=canvas.clientHeight;for(const o of state.obstacles){let rel=o.dist-state.raceDist;if(rel>-230&&rel<210){let y=H*.77-rel*.0011*H,scale=.24+Math.max(0,1-rel/360)*.73,x=laneX(o.lane,y,W);ctx.font=`${20*scale}px sans-serif`;ctx.textAlign='center';ctx.fillText(o.type==='cone'?'🚧':'🛢️',x,y);}}
for(const o of state.opponents){let rel=o.dist-state.raceDist;if(rel>-330&&rel<230){let y=H*.74-rel*.0009*H,scale=.33+Math.max(0,1-rel/440)*.62;drawCar(laneX(o.lane,y,W),y,31*scale,47*scale,o.color);}}
const py=H*.83;drawCar(laneX(state.playerLane,py,W),py,51,78,state.car.color,true);if(state.raceDist>raceLength-100){ctx.fillStyle='#e7e5d7';for(let i=0;i<12;i++){let x=i*W/12;ctx.fillRect(x,H*.39, W/12,(i%2===0)?7:0);ctx.fillStyle=i%2?'#171a20':'#f1f0e9';ctx.fillRect(x,H*.39+7,W/12,7);ctx.fillStyle='#e7e5d7';}}}
function raceLoop(now){if(!state.raceRunning)return;if(!state.lastFrame)state.lastFrame=now;let dt=Math.min(.04,(now-state.lastFrame)/1000);state.lastFrame=now;state.raceTime+=dt;state.gameFrame+=dt*60;
if(keys.left||touches.left)state.playerLane=Math.max(0,state.playerLane-2.8*dt);if(keys.right||touches.right)state.playerLane=Math.min(2,state.playerLane+2.8*dt);state.playerLane=Math.max(0,Math.min(2,state.playerLane));
let boosting=(keys.boost||touches.boost)&&state.boost>0;let speed=state.car.speed*(.76+(keys.up?.17:0)+(boosting?.28:0));if(boosting)state.boost=Math.max(0,state.boost-24*dt);else state.boost=Math.min(100,state.boost+7*dt);state.raceDist+=speed/3.6*dt;state.opponents.forEach(o=>o.dist+=o.speed/3.6*dt);
if(Math.random()<dt*.55&&state.obstacles.length<7){state.obstacles.push({lane:Math.floor(Math.random()*3),dist:state.raceDist+330+Math.random()*490,type:Math.random()<.58?'cone':'barrel'});}
for(let o of state.obstacles){if(!o.hit&&Math.abs(o.dist-state.raceDist)<9&&Math.abs(o.lane-state.playerLane)<.48){o.hit=true;state.carDamage=(state.carDamage||0)+1;state.raceDist=Math.max(0,state.raceDist-17);state.raceMessage='TRAFFIC! Keep it clean.';toast('Traffic hit — find a clear lane!');}}
state.obstacles=state.obstacles.filter(o=>o.dist>state.raceDist-100&&!o.hit);let place=1+state.opponents.filter(o=>o.dist>state.raceDist).length;$('#positionHud').textContent=Math.min(place,4)+' / 4';$('#speedHud').textContent=Math.round(speed);$('#boostHud').textContent=Math.round(state.boost)+'%';$('#topDistance').textContent=Math.min(raceLength,Math.round(state.raceDist))+' m';$('#raceProgress').style.width=Math.min(100,state.raceDist/raceLength*100)+'%';drawRace();if(state.raceDist>=raceLength){state.raceRunning=false;finishRace();return}requestAnimationFrame(raceLoop);}
function finishRace(){const place=1+state.opponents.filter(o=>o.dist>state.raceDist).length;const rewards=[6500,4000,2500,1200];const reward=rewards[Math.min(3,place-1)]+(place===1?state.round*1000:0);state.cash+=reward;if(place===1)state.roundsWon++;cashUpdate();$('#resultIcon').textContent=place===1?'🏆':place===2?'🥈':'🏁';$('#resultTitle').textContent=place===1?'Street legend.':place===2?'So close.':'Race complete.';$('#resultCopy').textContent=place===1?'You left them all in your mirrors. The underground is talking.':place===2?'One more clean line and that podium was yours. Keep building.':'A tough run, but every lap makes a better driver.';$('#resultPlace').textContent=['','1st','2nd','3rd','4th'][Math.min(4,place)];$('#resultTime').textContent='0'+Math.floor(state.raceTime/60)+':'+String(Math.floor(state.raceTime%60)).padStart(2,'0');$('#resultReward').textContent='+'+money(reward);$('#continueBtn').textContent=state.round<2?'NEXT AUCTION →':'SEASON RESULTS →';show('result');}
function endSeason(){show('result');$('#resultIcon').textContent=state.roundsWon>=2?'🏆':'🏁';$('#resultTitle').textContent=state.roundsWon>=2?'Circuit champion!':'Season complete.';$('#resultCopy').textContent=`You won ${state.roundsWon} of 3 races and took ${state.playerWon.length} auction ${state.playerWon.length===1?'ride':'rides'}.`;$('#resultPlace').textContent=state.roundsWon+'/3';$('#resultTime').textContent='SEASON';$('#resultReward').textContent=money(state.cash);$('#continueBtn').textContent='RACE AGAIN ↻';$('#continueBtn').onclick=resetGame;}
function resetGame(){state.cash=18000;state.round=0;state.car={name:'Starter Coupe',speed:168,accel:.98,handling:.95,color:'#d4fc43',stats:[6,6,6]};state.playerWon=[];state.roundsWon=0;$('#continueBtn').onclick=continueSeason;cashUpdate();show('home');}
function continueSeason(){if(state.round<2){state.round++;startAuction()}else{state.round++;endSeason()}}

